ker_urls":[],"compose_urls":["https://docs.xpipe.io/guide/webtop"],"truenas_scale_urls":[],"unraid_urls":[],"umbrel_urls":[],"yunohost_urls":[],"casaos_urls":[],"runtipi_urls":[],"cosmos_urls":[],"openmediavault_urls":[],"synology_urls":[],"qnap_urls":[],"proxmox_urls":[],"home_assistant_os_urls":[],"kubernetes_urls":[],"helm_urls":[],"native_urls":[],"binary_urls":[],"package_urls":[],"other_urls":[],"docker_images":[]},"reviewed_methods":["compose"]}]$release_installs$::jsonb;
  v_categories jsonb := $release_categories$[]$release_categories$::jsonb;
  item jsonb; field_name text; mismatch boolean; current_categories jsonb;
  current_app public.self_host_apps%rowtype; expected_app public.self_host_apps%rowtype;
  current_resource public.self_host_app_resource_estimates%rowtype; expected_resource public.self_host_app_resource_estimates%rowtype;
  current_install public.self_host_app_install_options%rowtype; expected_install public.self_host_app_install_options%rowtype;
begin
  perform set_config('lock_timeout','15000',true);
  perform id from public.self_host_apps where id in (select (value->>'app_id')::uuid from jsonb_array_elements(v_apps||v_resources||v_installs)) order by id for update;
  for item in select value from jsonb_array_elements(v_apps) loop
    select * into current_app from public.self_host_apps where id=(item->>'app_id')::uuid;
    if not found or current_app.slug is distinct from item->>'slug' then raise exception 'Missing release app %',item->>'slug';end if;
    select * into expected_app from jsonb_populate_record(null::public.self_host_apps,item->'expected');
    for field_name in select jsonb_object_keys(item->'expected') loop
      if field_name='categories' then
        select coalesce(jsonb_agg(c.slug order by c.slug),'[]'::jsonb) into current_categories from public.self_host_app_category_links l join public.self_host_app_categories c on c.id=l.category_id where l.app_id=current_app.id;
        mismatch := current_categories is distinct from item->'expected'->'categories';
      else
        execute format('select ($1).%I is distinct from ($2).%I',field_name,field_name) into mismatch using current_app,expected_app;
      end if;
      if mismatch then raise exception 'Release guard: % field % changed',current_app.slug,field_name;end if;
    end loop;
  end loop;
  for item in select value from jsonb_array_elements(v_resources) loop
    select * into current_app from public.self_host_apps where id=(item->>'app_id')::uuid;
    if not found then raise exception 'Missing resource app %',item->>'slug';end if;
    select * into expected_app from jsonb_populate_record(null::public.self_host_apps,item->'expected_app');
    for field_name in select jsonb_object_keys(item->'expected_app') loop
      execute format('select ($1).%I is distinct from ($2).%I',field_name,field_name) into mismatch using current_app,expected_app;
      if mismatch then raise exception 'Release resource identity guard: % field % changed',current_app.slug,field_name;end if;
    end loop;
    select * into current_resource from public.self_host_app_resource_estimates where app_id=current_app.id for update;
    if not found then raise exception 'Missing resource snapshot %',current_app.slug;end if;
    select * into expected_resource from jsonb_populate_record(null::public.self_host_app_resource_estimates,item->'expected');
    if current_resource is distinct from expected_resource then raise exception 'Release resource guard: % changed',current_app.slug;end if;
  end loop;
  for item in select value from jsonb_array_elements(v_installs) loop
    select * into current_install from public.self_host_app_install_options where app_id=(item->>'app_id')::uuid for update;
    if item->'expected'='null'::jsonb then
      if found then raise exception 'Release install appeared: %',item->>'slug';end if;
    else
      if not found then raise exception 'Missing install snapshot %',item->>'slug';end if;
      select * into expected_install from jsonb_populate_record(null::public.self_host_app_install_options,item->'expected');
      if current_install is distinct from expected_install then raise exception 'Release install guard: % changed',item->>'slug';end if;
    end if;
  end loop;
  insert into public.self_host_app_categories(slug,name,icon_key,sort_order)
    select slug,name,icon_key,sort_order from jsonb_to_recordset(v_categories) as x(slug text,name text,icon_key text,sort_order integer) on conflict(slug) do nothing;
  update public.self_host_apps app set
      name=case when x.value->'next' ? 'name' then proposed.name else app.name end,
      summary=case when x.value->'next' ? 'summary' then proposed.summary else app.summary end,
      icon_url=case when x.value->'next' ? 'icon_url' then proposed.icon_url else app.icon_url end,
      icon_source_url=case when x.value->'next' ? 'icon_source_url' then proposed.icon_source_url else app.icon_source_url end,
      website_url=case when x.value->'next' ? 'website_url' then proposed.website_url else app.website_url end,
      source_code_url=case when x.value->'next' ? 'source_code_url' then proposed.source_code_url else app.source_code_url end,
      source_code_host=case when x.value->'next' ? 'source_code_host' then proposed.source_code_host else app.source_code_host end,
      docs_url=case when x.value->'next' ? 'docs_url' then proposed.docs_url else app.docs_url end,
      install_docs_url=case when x.value->'next' ? 'install_docs_url' then proposed.install_docs_url else app.install_docs_url end,
      docker_url=case when x.value->'next' ? 'docker_url' then proposed.docker_url else app.docker_url end,
      license=case when x.value->'next' ? 'license' then proposed.license else app.license end,
      license_type=case when x.value->'next' ? 'license_type' then proposed.license_type else app.license_type end,
      license_spdx_id=case when x.value->'next' ? 'license_spdx_id' then proposed.license_spdx_id else app.license_spdx_id end,
      source_model=case when x.value->'next' ? 'source_model' then proposed.source_model else app.source_model end,
      publisher_name=case when x.value->'next' ? 'publisher_name' then proposed.publisher_name else app.publisher_name end,
      publisher_type=case when x.value->'next' ? 'publisher_type' then proposed.publisher_type else app.publisher_type end,
      publisher_url=case when x.value->'next' ? 'publisher_url' then proposed.publisher_url else app.publisher_url end,
      pricing_model=case when x.value->'next' ? 'pricing_model' then proposed.pricing_model else app.pricing_model end,
      published=case when x.value->'next' ? 'published' then proposed.published else app.published end,
      self_hosting_status=case when x.value->'next' ? 'self_hosting_status' then proposed.self_hosting_status else app.self_hosting_status end,
      maintenance_status=case when x.value->'next' ? 'maintenance_status' then proposed.maintenance_status else app.maintenance_status end,
      github_owner=case when x.value->'next' ? 'github_owner' then proposed.github_owner else app.github_owner end,
      github_repo=case when x.value->'next' ? 'github_repo' then proposed.github_repo else app.github_repo end,
      github_repo_id=case when x.value->'next' ? 'github_repo_id' then proposed.github_repo_id else app.github_repo_id end,
      github_project_id=case when x.value->'next' ? 'github_project_id' then proposed.github_project_id else app.github_project_id end,
      github_node_id=case when x.value->'next' ? 'github_node_id' then proposed.github_node_id else app.github_node_id end,
      github_full_name=case when x.value->'next' ? 'github_full_name' then proposed.github_full_name else app.github_full_name end,
      github_owner_type=case when x.value->'next' ? 'github_owner_type' then proposed.github_owner_type else app.github_owner_type end,
      github_stars=case when x.value->'next' ? 'github_stars' then proposed.github_stars else app.github_stars end,
      github_forks=case when x.value->'next' ? 'github_forks' then proposed.github_forks else app.github_forks end,
