      github_open_issues=case when x.value->'next' ? 'github_open_issues' then proposed.github_open_issues else app.github_open_issues end,
      github_primary_language=case when x.value->'next' ? 'github_primary_language' then proposed.github_primary_language else app.github_primary_language end,
      github_languages=case when x.value->'next' ? 'github_languages' then proposed.github_languages else app.github_languages end,
      github_topics=case when x.value->'next' ? 'github_topics' then proposed.github_topics else app.github_topics end,
      github_created_at=case when x.value->'next' ? 'github_created_at' then proposed.github_created_at else app.github_created_at end,
