      github_pushed_at=case when x.value->'next' ? 'github_pushed_at' then proposed.github_pushed_at else app.github_pushed_at end,
      github_default_branch=case when x.value->'next' ? 'github_default_branch' then proposed.github_default_branch else app.github_default_branch end,
      github_repo_size_kb=case when x.value->'next' ? 'github_repo_size_kb' then proposed.github_repo_size_kb else app.github_repo_size_kb end,
      github_archived=case when x.value->'next' ? 'github_archived' then proposed.github_archived else app.github_archived end,
      github_disabled=case when x.value->'next' ? 'github_disabled' then proposed.github_disabled else app.github_disabled end,
      github_is_fork=case when x.value->'next' ? 'github_is_fork' then proposed.github_is_fork else app.github_is_fork end,
      github_is_template=case when x.value->'next' ? 'github_is_template' then proposed.github_is_template else app.github_is_template end,
      source_repo_id=case when x.value->'next' ? 'source_repo_id' then proposed.source_repo_id else app.source_repo_id end,
      source_full_name=case when x.value->'next' ? 'source_full_name' then proposed.source_full_name else app.source_full_name end,
      source_stars=case when x.value->'next' ? 'source_stars' then proposed.source_stars else app.source_stars end,
      source_forks=case when x.value->'next' ? 'source_forks' then proposed.source_forks else app.source_forks end,
