      source_open_issues=case when x.value->'next' ? 'source_open_issues' then proposed.source_open_issues else app.source_open_issues end,
      source_primary_language=case when x.value->'next' ? 'source_primary_language' then proposed.source_primary_language else app.source_primary_language end,
      source_languages=case when x.value->'next' ? 'source_languages' then proposed.source_languages else app.source_languages end,
