      data_source_urls=array(select distinct source from unnest(coalesce(app.data_source_urls,'{}')||array(select jsonb_array_elements_text(x.value->'data_source_urls'))) source where source is not null order by source),updated_at=now()
    from jsonb_array_elements(v_apps) x(value) cross join lateral jsonb_populate_record(null::public.self_host_apps,x.value->'next') proposed where app.id=(x.value->>'app_id')::uuid;
  for item in select value from jsonb_array_elements(v_apps) where value->'next' ? 'categories' loop
    delete from public.self_host_app_category_links where app_id=(item->>'app_id')::uuid;
    insert into public.self_host_app_category_links(app_id,category_id)
      select (item->>'app_id')::uuid,c.id from jsonb_array_elements_text(item->'next'->'categories') requested(slug) join public.self_host_app_categories c on c.slug=requested.slug;
    if (select count(*) from public.self_host_app_category_links where app_id=(item->>'app_id')::uuid) <> jsonb_array_length(item->'next'->'categories') then raise exception 'Missing release category %',item->>'slug';end if;
  end loop;
  insert into public.self_host_app_install_options (app_id,options,catalog_sources,source_urls,checked_at,docker_urls,compose_urls,truenas_scale_urls,unraid_urls,umbrel_urls,yunohost_urls,casaos_urls,runtipi_urls,cosmos_urls,openmediavault_urls,synology_urls,qnap_urls,proxmox_urls,home_assistant_os_urls,kubernetes_urls,helm_urls,native_urls,binary_urls,package_urls,other_urls,docker_images)
    select app_id,options,catalog_sources,source_urls,checked_at,docker_urls,compose_urls,truenas_scale_urls,unraid_urls,umbrel_urls,yunohost_urls,casaos_urls,runtipi_urls,cosmos_urls,openmediavault_urls,synology_urls,qnap_urls,proxmox_urls,home_assistant_os_urls,kubernetes_urls,helm_urls,native_urls,binary_urls,package_urls,other_urls,docker_images from jsonb_populate_recordset(null::public.self_host_app_install_options,(select jsonb_agg(x.value->'next') from jsonb_array_elements(v_installs) x(value)))
    on conflict(app_id) do update set options=excluded.options,catalog_sources=excluded.catalog_sources,source_urls=excluded.source_urls,checked_at=excluded.checked_at,docker_urls=excluded.docker_urls,compose_urls=excluded.compose_urls,truenas_scale_urls=excluded.truenas_scale_urls,unraid_urls=excluded.unraid_urls,umbrel_urls=excluded.umbrel_urls,yunohost_urls=excluded.yunohost_urls,casaos_urls=excluded.casaos_urls,runtipi_urls=excluded.runtipi_urls,cosmos_urls=excluded.cosmos_urls,openmediavault_urls=excluded.openmediavault_urls,synology_urls=excluded.synology_urls,qnap_urls=excluded.qnap_urls,proxmox_urls=excluded.proxmox_urls,home_assistant_os_urls=excluded.home_assistant_os_urls,kubernetes_urls=excluded.kubernetes_urls,helm_urls=excluded.helm_urls,native_urls=excluded.native_urls,binary_urls=excluded.binary_urls,package_urls=excluded.package_urls,other_urls=excluded.other_urls,docker_images=excluded.docker_images,updated_at=now();
  insert into public.self_host_app_resource_estimates (app_id,ram_note,checked_at,storage_note,ram_source_urls,ram_estimate_kind,ram_estimate_basis,ram_estimate_max_mb,ram_estimate_min_mb,storage_source_urls,storage_estimate_kind,storage_estimate_basis,ram_estimate_confidence,storage_estimate_max_gb,storage_estimate_min_gb,storage_estimate_confidence)
    select app_id,ram_note,checked_at,storage_note,ram_source_urls,ram_estimate_kind,ram_estimate_basis,ram_estimate_max_mb,ram_estimate_min_mb,storage_source_urls,storage_estimate_kind,storage_estimate_basis,ram_estimate_confidence,storage_estimate_max_gb,storage_estimate_min_gb,storage_estimate_confidence from jsonb_populate_recordset(null::public.self_host_app_resource_estimates,(select jsonb_agg(x.value->'next') from jsonb_array_elements(v_resources) x(value)))
    on conflict(app_id) do update set ram_note=excluded.ram_note,checked_at=excluded.checked_at,storage_note=excluded.storage_note,ram_source_urls=excluded.ram_source_urls,ram_estimate_kind=excluded.ram_estimate_kind,ram_estimate_basis=excluded.ram_estimate_basis,ram_estimate_max_mb=excluded.ram_estimate_max_mb,ram_estimate_min_mb=excluded.ram_estimate_min_mb,storage_source_urls=excluded.storage_source_urls,storage_estimate_kind=excluded.storage_estimate_kind,storage_estimate_basis=excluded.storage_estimate_basis,ram_estimate_confidence=excluded.ram_estimate_confidence,storage_estimate_max_gb=excluded.storage_estimate_max_gb,storage_estimate_min_gb=excluded.storage_estimate_min_gb,storage_estimate_confidence=excluded.storage_estimate_confidence,updated_at=now();
  for item in select value from jsonb_array_elements(v_apps) loop
    select * into current_app from public.self_host_apps where id=(item->>'app_id')::uuid;
    select * into expected_app from jsonb_populate_record(null::public.self_host_apps,item->'next');
    for field_name in select key from jsonb_object_keys(item->'next') keys(key) where key<>'categories' loop
      execute format('select ($1).%I is distinct from ($2).%I',field_name,field_name) into mismatch using current_app,expected_app;
      if mismatch then raise exception 'Release app readback: % field % differs',current_app.slug,field_name;end if;
    end loop;
  end loop;
  for item in select value from jsonb_array_elements(v_resources) loop
    select * into current_resource from public.self_host_app_resource_estimates where app_id=(item->>'app_id')::uuid;
    select * into expected_resource from jsonb_populate_record(null::public.self_host_app_resource_estimates,item->'next');
    if (to_jsonb(current_resource)-'created_at'-'updated_at') is distinct from (to_jsonb(expected_resource)-'created_at'-'updated_at') then raise exception 'Release resource readback: % differs',item->>'slug';end if;
    if (select source_code_url from public.self_host_apps where id=(item->>'app_id')::uuid) is distinct from item->>'source_after' then raise exception 'Release source readback: % differs',item->>'slug';end if;
  end loop;
  for item in select value from jsonb_array_elements(v_installs) loop
    select * into current_install from public.self_host_app_install_options where app_id=(item->>'app_id')::uuid;
    select * into expected_install from jsonb_populate_record(null::public.self_host_app_install_options,item->'next');
    if (to_jsonb(current_install)-'created_at'-'updated_at') is distinct from (to_jsonb(expected_install)-'created_at'-'updated_at') then raise exception 'Release install readback: % differs',item->>'slug';end if;
  end loop;
end
$self_host_apps_release$;
